    function obterIniciaisUsuario(nome = "") {
      return String(nome || "")
        .trim()
        .split(/\s+/)
        .filter(Boolean)
        .slice(0, 2)
        .map((parte) => parte.charAt(0).toUpperCase())
        .join("") || "PR";
    }

    function chaveAvatarPerfilLocal(user = authUser) {
      const id = user?.id || user?.email || "local";
      return `prioriza_avatar_cache_${id}`;
    }

    function obterAvatarPerfilLocal(user = authUser) {
      try {
        return localStorage.getItem(chaveAvatarPerfilLocal(user)) || "";
      } catch {
        return "";
      }
    }

    function salvarAvatarPerfilLocal(user, dataUrl) {
      if (!user || !dataUrl) return;
      try {
        localStorage.setItem(chaveAvatarPerfilLocal(user), dataUrl);
      } catch (e) {
        console.warn("[PRIORIZA] Não foi possível manter cache local do avatar:", e);
      }
    }

    function removerAvatarPerfilLocal(user = authUser) {
      try {
        localStorage.removeItem(chaveAvatarPerfilLocal(user));
      } catch {}
    }

    async function prepararAvatarPerfilLocal(arquivo) {
      if (!arquivo || !String(arquivo.type || "").startsWith("image/")) return "";
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = reject;
        reader.readAsDataURL(arquivo);
      });
      if (arquivo.type === "image/gif") return dataUrl;

      const img = await new Promise((resolve, reject) => {
        const imagem = new Image();
        imagem.onload = () => resolve(imagem);
        imagem.onerror = reject;
        imagem.src = dataUrl;
      });
      const max = 320;
      const escala = Math.min(1, max / img.naturalWidth, max / img.naturalHeight);
      const largura = Math.max(1, Math.round(img.naturalWidth * escala));
      const altura = Math.max(1, Math.round(img.naturalHeight * escala));
      const canvas = document.createElement("canvas");
      canvas.width = largura;
      canvas.height = altura;
      const ctx = canvas.getContext("2d");
      ctx.clearRect(0, 0, largura, altura);
      ctx.drawImage(img, 0, 0, largura, altura);
      return canvas.toDataURL("image/webp", 0.86);
    }

    function renderizarAvatarPerfil(el, nome, avatarUrl) {
      if (!el) return;
      const iniciais = obterIniciaisUsuario(nome);
      const avatarLocal = obterAvatarPerfilLocal();
      const fonteAvatar = avatarUrl || avatarLocal;
      if (fonteAvatar) {
        el.classList.add("has-photo");
        const img = document.createElement("img");
        img.src = fonteAvatar;
        img.alt = `Foto de perfil de ${nome || "usuário"}`;
        img.loading = "lazy";
        el.replaceChildren(img);
        if (img) {
          img.addEventListener("error", () => {
            if (avatarUrl && avatarLocal && img.src !== avatarLocal) {
              img.src = avatarLocal;
              return;
            }
            el.classList.remove("has-photo");
            el.textContent = iniciais;
          }, { once: true });
        }
        return;
      }
      el.classList.remove("has-photo");
      el.textContent = iniciais;
    }

