    function atualizarTelaAjustes() {
      const main = document.getElementById("settings-main-view");
      const detail = document.getElementById("settings-detail-view");
      const shell = document.querySelector("#screen-ajustes .settings-native-shell");
      if (!main || !detail) return;
      const desktop = window.matchMedia("(min-width: 1100px)").matches;
      const mostrandoDetalhe = !!settingsPageAtual;
      main.hidden = mostrandoDetalhe;
      shell?.classList.toggle("settings-detail-open", mostrandoDetalhe && desktop);
      if (mostrandoDetalhe) {
        detail.hidden = false;
        requestAnimationFrame(() => detail.classList.add("is-open"));
      } else {
        detail.classList.remove("is-open");
        window.setTimeout(() => {
          if (!settingsPageAtual) detail.hidden = true;
        }, desktop ? 220 : 180);
      }
      detail.querySelectorAll("[data-settings-page]").forEach((page) => {
        page.hidden = page.dataset.settingsPage !== settingsPageAtual;
      });
    }

