    async function enviarAvatarPerfil(arquivo) {
      if (!arquivo) return;
      const formData = new FormData();
      formData.append("arquivo", arquivo);
      const btn = document.getElementById("btn-upload-avatar");
      const btnRemover = document.getElementById("btn-remover-avatar");
      const input = document.getElementById("input-avatar-upload");
      if (btn) {
        btn.disabled = true;
        btn.textContent = "Enviando...";
      }
      if (btnRemover) btnRemover.disabled = true;
      try {
        const avatarLocalDataUrl = await prepararAvatarPerfilLocal(arquivo);
        const res = await apiFetch(API + "/auth/profile/avatar", {
          method: "POST",
          body: formData,
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.detail || "Não foi possível atualizar a foto de perfil.");
        salvarAvatarPerfilLocal(data?.user || authUser, avatarLocalDataUrl);
        atualizarUsuarioAutenticado(data?.user);
        await modal.alerta(data?.message || "Foto de perfil atualizada com sucesso.", "Perfil");
      } catch (e) {
        await modal.alerta(e.message || "Não foi possível atualizar a foto de perfil.", "Perfil");
      } finally {
        if (input) input.value = "";
        if (btn) {
          btn.disabled = false;
          btn.textContent = "Atualizar foto";
        }
        if (btnRemover) btnRemover.disabled = false;
      }
    }

