    async function alterarSenhaConta() {
      const senhaAtual = document.getElementById("conta-senha-atual")?.value || "";
      const novaSenha = document.getElementById("conta-nova-senha")?.value || "";
      const confirmarSenha = document.getElementById("conta-confirmar-senha")?.value || "";
      const statusEl = document.getElementById("conta-status");
      const btn = document.getElementById("btn-salvar-nova-senha");
      if (statusEl) statusEl.textContent = "";

      if (!senhaAtual || !novaSenha || !confirmarSenha) {
        if (statusEl) statusEl.textContent = "Preencha todos os campos para alterar a senha.";
        return;
      }
      if (novaSenha.length < 6) {
        if (statusEl) statusEl.textContent = "A nova senha precisa ter pelo menos 6 caracteres.";
        return;
      }
      if (novaSenha !== confirmarSenha) {
        if (statusEl) statusEl.textContent = "As senhas não coincidem.";
        return;
      }

      if (btn) {
        btn.disabled = true;
        btn.textContent = "Salvando...";
      }
      try {
        const res = await apiFetch(API + "/auth/change-password", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            senha_atual: senhaAtual,
            nova_senha: novaSenha,
            confirmar_senha: confirmarSenha,
          }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.detail || "Não foi possível atualizar a senha.");
        document.getElementById("form-alterar-senha-ajustes")?.reset();
        if (statusEl) statusEl.textContent = data?.message || "Senha atualizada com sucesso.";
      } catch (e) {
        if (statusEl) statusEl.textContent = e.message || "Não foi possível atualizar a senha.";
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.textContent = "Salvar nova senha";
        }
      }
    }

