    async function excluirContaAtual(ev = null) {
      ev?.preventDefault?.();
      const senhaEl = document.getElementById("excluir-conta-senha");
      const confirmacaoEl = document.getElementById("excluir-conta-confirmacao");
      const erro = document.getElementById("excluir-conta-modal-erro");
      const btn = document.getElementById("btn-confirmar-exclusao-conta");
      const btnCancelar = document.getElementById("btn-cancelar-exclusao-conta");
      const senha = senhaEl?.value || "";
      const confirmacao = confirmacaoEl?.value || "";
      if (erro) erro.textContent = "";
      if (!senha.trim() || confirmacao.trim() !== "EXCLUIR") {
        if (erro) erro.textContent = "Informe sua senha atual e digite EXCLUIR para confirmar.";
        atualizarBotaoExclusaoConta();
        return;
      }
      document.querySelectorAll("#form-excluir-conta input, #form-excluir-conta button").forEach((el) => {
        el.disabled = true;
      });
      if (btn) btn.textContent = "Excluindo conta...";
      try {
        const res = await apiFetch(API + "/auth/account", {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ senha, confirmacao: "EXCLUIR" }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.detail || "Não foi possível excluir sua conta.");
        limparAvatarPerfilLocal(authUser);
        authUser = null;
        clearAuthToken();
        demoStatusAtual = null;
        fecharModalExclusaoConta();
        await modal.alerta(data?.message || "Conta excluída com sucesso.", "Conta excluída");
        window.location.reload();
      } catch (e) {
        if (erro) erro.textContent = e.message || "Não foi possível excluir sua conta.";
        document.querySelectorAll("#form-excluir-conta input, #form-excluir-conta button").forEach((el) => {
          el.disabled = false;
        });
        if (btn) btn.textContent = "Excluir minha conta";
        if (btnCancelar) btnCancelar.textContent = "Cancelar";
        atualizarBotaoExclusaoConta();
      }
    }

    async function carregarSessoesRecentes() {
      const lista = document.getElementById("privacidade-sessoes-lista");
      const statusEl = document.getElementById("privacidade-sessoes-status");
      if (!lista || !statusEl) return;
      statusEl.textContent = "Atualizando acessos recentes...";
      lista.innerHTML = "";
      try {
        const res = await apiFetch(API + "/auth/sessions", { headers: authHeaders() });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.detail || "Não foi possível carregar as sessões recentes.");
        const expiraEm = data?.sessao_atual?.expira_em ? formatarDataHoraAdmin(data.sessao_atual.expira_em) : "Não disponível";
        const sessoes = Array.isArray(data?.sessoes_recentes) ? data.sessoes_recentes : [];
        statusEl.textContent = `Sessão atual válida até ${expiraEm}.`;
        const sessaoMaisRecente = sessoes[0];
        if (!sessaoMaisRecente) {
          lista.innerHTML = `
            <div class="settings-detail-item">
              <strong>Último acesso</strong>
              <span>Ainda não há um registro recente para mostrar.</span>
            </div>
          `;
          return;
        }
        lista.innerHTML = `
          <div class="settings-detail-item">
            <strong>Acesso mais recente</strong>
            <span>${formatarDataHoraAdmin(sessaoMaisRecente.acessado_em)}</span>
          </div>
        `;
      } catch (e) {
        statusEl.textContent = e.message || "Não foi possível carregar as sessões recentes.";
      }
    }

