    async function enviarFeedbackAjustes(categoria) {
      const rotulos = {
        feedback: "feedback",
        problema: "problema",
        melhoria: "melhoria",
      };
      const rotulo = rotulos[categoria] || "feedback";
      const mensagem = await modal.perguntar(
        `Escreva seu ${rotulo} para o time do PRIORIZA.`,
        "Ajuda e feedback",
        "Digite sua mensagem"
      );
      if (mensagem === null) return;
      const texto = String(mensagem || "").trim();
      if (texto.length < 8) {
        await modal.alerta("Escreva uma mensagem um pouco mais detalhada para continuar.", "Ajuda e feedback");
        return;
      }
      const statusEl = document.getElementById("ajuda-feedback-status");
      if (statusEl) statusEl.textContent = "Enviando sua mensagem...";
      try {
        const res = await apiFetch(API + "/feedback", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ categoria, mensagem: texto }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data?.detail || "Não foi possível enviar sua mensagem.");
        if (statusEl) statusEl.textContent = data?.message || "Mensagem enviada com sucesso.";
      } catch (e) {
        if (statusEl) statusEl.textContent = e.message || "Não foi possível enviar sua mensagem.";
      }
    }

    async function abrirPlaceholderAjustes(acao) {
      const alvo = acao || "Este recurso";
      await modal.alerta(`${alvo} está em preparação para uma próxima versão do PRIORIZA.`, "Em breve");
    }
